// ---------- CONFIG ----------
const MY_EMAIL = 'liemormarvin@example.com';          // skip anything sent from you
const EXEC_NAME = 'Marvin';           // used in the prompt
const VIP_SENDERS = ['CEO'];                      // e.g. ['ceo@client.com', 'board@']
const URGENT_HINTS = ['urgent', 'asap', 'deadline', 'today', 'EOD', 'immediately', 'invoice overdue'];
const MAX_EMAILS = 60;
const SNIPPET_CHARS = 500;
// ----------------------------

const header = (j, name) => {
  if (j[name] !== undefined) return j[name];                                   // Simplify ON (From / Subject)
  if (j.headers && (j.headers[name] ?? j.headers[name.toLowerCase()]) !== undefined) {
    return j.headers[name] ?? j.headers[name.toLowerCase()];
  }
  const h = j.payload?.headers?.find(h => h.name?.toLowerCase() === name.toLowerCase()); // Simplify OFF
  return h?.value ?? '';
};

const parseSender = (from = '') => {
  const m = from.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  return m
    ? { name: m[1].trim() || m[2], email: m[2].trim().toLowerCase() }
    : { name: from.trim(), email: from.trim().toLowerCase() };
};

const clean = (s = '') =>
  String(s)
    .replace(/<[^>]+>/g, ' ')
    .replace(/https?:\/\/\S+/g, '[link]')
    .replace(/\s+/g, ' ')
    .trim();

// Normalize + drop empties / own mail
let emails = $input.all()
  .map(item => item.json)
  .filter(j => j && j.id)
  .map(j => {
    const from = parseSender(header(j, 'From'));
    return {
      id: j.id,
      threadId: j.threadId || j.id,
      subject: String(header(j, 'Subject')).replace(/\s+/g, ' ').trim() || '(no subject)',
      fromName: from.name,
      fromEmail: from.email,
      snippet: clean(j.text || j.snippet || '').slice(0, SNIPPET_CHARS),
      receivedAt: j.internalDate ? Number(j.internalDate) : Date.parse(header(j, 'Date')) || 0,
      isVip: VIP_SENDERS.some(v => `${from.name} ${from.email}`.toLowerCase().includes(v.toLowerCase())),
    };
  })
  .filter(e => !e.fromEmail.includes(MY_EMAIL.toLowerCase()));

// One entry per thread (keep newest), newest first
const byThread = new Map();
for (const e of emails) {
  const prev = byThread.get(e.threadId);
  if (!prev || e.receivedAt > prev.receivedAt) byThread.set(e.threadId, e);
}
emails = [...byThread.values()]
  .sort((a, b) => b.receivedAt - a.receivedAt)
  .slice(0, MAX_EMAILS)
  .map((e, i) => ({ ...e, ref: `e${i + 1}` }));

if (emails.length === 0) {
  return [{ json: { total: 0, prompt: '', emails: [] } }];
}

const emailBlock = emails.map(e =>
  JSON.stringify({
    ref: e.ref,
    from: `${e.fromName} <${e.fromEmail}>`,
    vip: e.isVip,
    subject: e.subject,
    preview: e.snippet,
  })
).join('\n');

const prompt = `You are an executive assistant triaging the overnight inbox for ${EXEC_NAME}.
Classify EVERY email below into exactly one category:

- "urgent": time-sensitive, has a deadline within ~24h, comes from a VIP, or something breaks/costs money if ignored. Hint words: ${URGENT_HINTS.join(', ')}.
- "needs_reply": a real person expects an answer or decision, but it is not time-critical.
- "fyi": informational only (receipts, confirmations, status updates, newsletters worth a glance). No action needed.
- "spam": cold outreach, marketing, promotions, or low-value noise.

For each email return:
- "ref": the ref exactly as given
- "category": one of urgent | needs_reply | fyi | spam
- "priority": integer 1-5 (5 = most important), used for sorting within a category
- "summary": one plain sentence, max 20 words, saying what the email actually says
- "action": for urgent/needs_reply, the concrete next step in max 10 words. Otherwise "".

Rules:
- Return ONLY a JSON array with one object per email. No markdown, no commentary.
- Do not invent details that are not in the email.
- When unsure between two categories, choose the more important one.

EMAILS (one JSON object per line):
${emailBlock}`;

return [{ json: { total: emails.length, prompt, emails } }];

// ---------- CONFIG ----------
const TZ = 'Asia/Manila';
const LOOKBACK_HOURS = 12;   // keep in sync with the Gmail search expression
const MAX_FYI_SHOWN = 15;
const MAX_SPAM_TITLES = 8;
// ----------------------------

const prep = $('Prep Emails').first().json;

const esc = (s = '') => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linkText = (s = '') => esc(s).replace(/\|/g, '/');
const gmailUrl = (e) => `https://mail.google.com/mail/u/0/#inbox/${e.threadId}`;
const trunc = (s = '', n = 90) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

const dateLabel = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ, weekday: 'short', month: 'short', day: 'numeric',
}).format(new Date());

// ---- Empty inbox path ----
if (!prep.total) {
  const text = `☀️ Inbox briefing — ${dateLabel}: nothing new in the last ${LOOKBACK_HOURS}h. Inbox is clear. ✅`;
  return [{ json: { text, blocks: [{ type: 'section', text: { type: 'mrkdwn', text } }] } }];
}

// ---- Parse Gemini output ----
const raw = $input.first().json;

const partText = (p) => (typeof p?.text === 'string' ? p.text : JSON.stringify(p?.text ?? ''));
const rawText =
  raw?.content?.parts?.map(partText).join('') ??
  raw?.candidates?.[0]?.content?.parts?.map(partText).join('') ??
  raw?.text ?? raw?.output ??
  (typeof raw === 'string' ? raw : JSON.stringify(raw));

let results = [];
let parseFailed = false;
let failReason = '';
try {
  if (raw?.error) {
    throw new Error(typeof raw.error === 'string' ? raw.error : (raw.error.message || JSON.stringify(raw.error)));
  }
  const stripped = String(rawText).replace(/```json|```/gi, '').trim();
  const start = stripped.indexOf('[');
  const end = stripped.lastIndexOf(']');
  results = JSON.parse(stripped.slice(start, end + 1));
  if (!Array.isArray(results)) throw new Error('not an array');
} catch (err) {
  parseFailed = true;
  failReason = String(err.message || err).slice(0, 160);
}

const byRef = new Map(results.map(r => [String(r.ref), r]));
const VALID = ['urgent', 'needs_reply', 'fyi', 'spam'];

// ---- Merge AI results back onto the real emails ----
const items = prep.emails.map(e => {
  const r = byRef.get(e.ref);
  const category = r && VALID.includes(r.category) ? r.category : 'needs_reply'; // fail safe: surface it
  return {
    ...e,
    category,
    priority: Number(r?.priority) || 3,
    summary: r?.summary || e.snippet.slice(0, 120) || '(no preview)',
    action: r?.action || '',
    unclassified: !r,
  };
});

const bucket = (cat) =>
  items
    .filter(i => i.category === cat)
    .sort((a, b) => b.priority - a.priority || b.receivedAt - a.receivedAt);

const urgent = bucket('urgent');
const needsReply = bucket('needs_reply');
const fyi = bucket('fyi');
const spam = bucket('spam');

// ---- Slack formatting helpers ----
const line = (i) => {
  const vip = i.isVip ? ' ⭐' : '';
  const head = `• <${gmailUrl(i)}|*${linkText(trunc(i.subject, 80))}*> — ${esc(trunc(i.fromName, 40))}${vip}`;
  const body = `\n      _${esc(i.summary)}_`;
  const act = i.action ? ` → *${esc(i.action)}*` : '';
  return head + body + act;
};

const sectionBlocks = (title, arr, cap = Infinity) => {
  if (!arr.length) return [];
  const shown = arr.slice(0, cap);
  const lines = shown.map(line);
  if (arr.length > shown.length) lines.push(`_…and ${arr.length - shown.length} more_`);

  // Slack section text limit is 3000 chars → chunk it
  const chunks = [];
  let cur = '';
  for (const l of lines) {
    if ((cur + '\n' + l).length > 2800) { chunks.push(cur); cur = l; }
    else cur = cur ? cur + '\n' + l : l;
  }
  if (cur) chunks.push(cur);

  return chunks.map((c, idx) => ({
    type: 'section',
    text: { type: 'mrkdwn', text: idx === 0 ? `*${title} (${arr.length})*\n${c}` : c },
  }));
};

// ---- Assemble blocks ----
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `☀️ Inbox briefing — ${dateLabel}` } },
  {
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `${items.length} threads in the last ${LOOKBACK_HOURS}h  •  🔴 ${urgent.length} urgent  •  🟡 ${needsReply.length} need reply  •  🔵 ${fyi.length} FYI  •  🗑️ ${spam.length} spam-ish`,
    }],
  },
  { type: 'divider' },
];

if (parseFailed) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `⚠️ _AI categorization failed (${esc(failReason)}) — everything below is listed as "needs reply"._` },
  });
}

blocks.push(...sectionBlocks('🔴 Urgent', urgent));
if (urgent.length) blocks.push({ type: 'divider' });

blocks.push(...sectionBlocks('🟡 Needs reply', needsReply));
if (needsReply.length) blocks.push({ type: 'divider' });

blocks.push(...sectionBlocks('🔵 FYI', fyi, MAX_FYI_SHOWN));

if (spam.length) {
  const titles = spam.slice(0, MAX_SPAM_TITLES).map(s => esc(trunc(s.subject, 40))).join(' · ');
  const more = spam.length > MAX_SPAM_TITLES ? ` · +${spam.length - MAX_SPAM_TITLES} more` : '';
  blocks.push({ type: 'divider' });
  blocks.push({
    type: 'context',
    elements: [{ type: 'mrkdwn', text: `🗑️ *Spam-ish (${spam.length}):* ${titles}${more}` }],
  });
}

// Slack hard cap is 50 blocks
const finalBlocks = blocks.slice(0, 50);

const text = `Inbox briefing ${dateLabel}: ${urgent.length} urgent, ${needsReply.length} need reply, ${fyi.length} FYI, ${spam.length} spam-ish`;

return [{ json: { text, blocks: finalBlocks } }];
